function drawEdges(){if(view==='timeline')return;$('#edges').innerHTML=edges.map((e,i)=>{const a=nodes.find(x=>x.id===e.from),b=nodes.find(x=>x.id===e.to);const x=e.vertical?a.x+a.w/2:a.x+a.w,y=e.vertical?a.y+a.h:a.y+a.h/2,tx=e.vertical?b.x+b.w/2:b.x,ty=e.vertical?b.y:b.y+b.h/2,transfer=e.kind==='Base transferible',dashed=['Base transferible','Transversal','Integración condicionada'].includes(e.kind),bend=Math.max(28,(tx-x)/2),curve=e.overview?`M ${x} ${y} L ${x} ${ty-26} L ${tx} ${ty-26} L ${tx} ${ty}`:e.vertical?`M ${x} ${y} C ${x} ${y+40},${tx} ${ty-40},${tx} ${ty}`:`M ${x} ${y} C ${x+bend} ${y},${tx-bend} ${ty},${tx} ${ty}`,color=transfer?'#d52415':e.kind==='Familia del atlas'?'#00d2dc':'#65cbd0';return `<path class="edge-line ${dashed?'edge-dashed':''}" d="${curve}" stroke-width="1.8" fill="none" style="stroke:${color}"><title>${esc(e.kind)}</title></path><path class="edge-pulse" d="${curve}" stroke-width="2.8" fill="none" style="stroke:${transfer?'#ff5a4d':'#a9fcff'};animation-delay:-${(i*.55).toFixed(2)}s" aria-hidden="true"/><circle class="edge-end" cx="${tx}" cy="${ty}" r="4" style="fill:${color}" aria-hidden="true"/>`}).join('')}
