function fitGraph(fitAll=false){if(view==='list'||!nodes.length)return;const box=$('#graph').getBoundingClientRect();graphSize={w:box.width,h:box.height};const maxX=Math.max(...nodes.map(n=>n.x+n.w)),maxY=Math.max(...nodes.map(n=>n.y+n.h)),minX=Math.min(...nodes.map(n=>n.x)),minY=Math.min(...nodes.map(n=>n.y));const overview=selected.type==='overview',top=overview?innerWidth<601?205:innerWidth<761?185:150:innerWidth<601?290:280,bottomReserve=overview?170:185,availH=Math.max(150,box.height-top-bottomReserve),availW=Math.max(240,box.width-(innerWidth<601?30:80));camera.k=Math.min(1.12,availW/(maxX-minX),availH/(maxY-minY));camera.k=Math.max(fitAll===true?.25:Math.min(.9,availW/(maxX-minX)),camera.k);camera.x=(box.width-(maxX-minX)*camera.k)/2-minX*camera.k;camera.y=top+Math.max(0,(availH-(maxY-minY)*camera.k)/2)-minY*camera.k;applyCamera()}
